import pyomo.environ as pyo

DATA = {
    "table_types": ["circular", "rectangular"],
    "guests_per_table": {"circular": 8, "rectangular": 12},
    "participants_per_table": {"circular": 5, "rectangular": 4},
    "posterboards_per_table": {"circular": 4, "rectangular": 4},
    "space_per_table": {"circular": 15, "rectangular": 20},
    "min_participants": 500,
    "min_posterboards": 300,
    "available_space": 1900,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.T = pyo.Set(initialize=d["table_types"])

    model.tables = pyo.Var(
        model.T,
        within=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["guests_per_table"][t] * m.tables[t] for t in m.T)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.maximize)

    def participants_rule(m):
        return sum(
            d["participants_per_table"][t] * m.tables[t] for t in m.T
        ) >= d["min_participants"]

    model.participants_constraint = pyo.Constraint(rule=participants_rule)

    def posterboards_rule(m):
        return sum(
            d["posterboards_per_table"][t] * m.tables[t] for t in m.T
        ) >= d["min_posterboards"]

    model.posterboards_constraint = pyo.Constraint(rule=posterboards_rule)

    def space_rule(m):
        return sum(
            d["space_per_table"][t] * m.tables[t] for t in m.T
        ) <= d["available_space"]

    model.space_constraint = pyo.Constraint(rule=space_rule)

    return model


